describe('cursor-extraction: malformed JSONL tolerance', () => {
  it('skips truncated/malformed lines and returns the last valid match', () => {
    const validLine = JSON.stringify({
      role: 'assistant',
      message: { content: [{ type: 'text', text: 'recovered text' }] },
    });
    const malformed = '{"role":"assistant","message":{"content":[{"type":"tex'; // truncated mid-write
    const content = [validLine, malformed].join('\n');

    expect(() => extractLastMessageFromJsonl(content, 'assistant', false)).not.toThrow();
    expect(extractLastMessageFromJsonl(content, 'assistant', false)).toBe('recovered text');
  });

  it('returns empty string when ALL lines are malformed', () => {
    const content = ['{partial', 'not even close to json', '}{'].join('\n');
    expect(extractLastMessageFromJsonl(content, 'assistant', false)).toBe('');
  });

  // CodeRabbit Major + Greptile P1 (PR #2282 follow-up): a valid JSON line
  // whose `message.content` is an unexpected type (null, number, plain
  // object) used to throw. It must now be skipped — same tolerance class as
  // truncated lines.
  it('skips a line whose message.content is null and falls back to a valid earlier line', () => {
    const valid = JSON.stringify({
      role: 'assistant',
      message: { content: [{ type: 'text', text: 'kept' }] },
    });
    const nullContent = JSON.stringify({
      role: 'assistant',
      message: { content: null },
    });
    const content = [valid, nullContent].join('\n');

    expect(() => extractLastMessageFromJsonl(content, 'assistant', false)).not.toThrow();
    expect(extractLastMessageFromJsonl(content, 'assistant', false)).toBe('kept');
  });

  it('skips a line whose message.content is a number without throwing', () => {
    const valid = JSON.stringify({
      role: 'assistant',
      message: { content: [{ type: 'text', text: 'kept too' }] },
    });
    const numericContent = JSON.stringify({
      role: 'assistant',
      message: { content: 42 },
    });
    const content = [valid, numericContent].join('\n');

    expect(() => extractLastMessageFromJsonl(content, 'assistant', false)).not.toThrow();
    expect(extractLastMessageFromJsonl(content, 'assistant', false)).toBe('kept too');
  });

  it('skips a line whose message.content is a plain object without throwing', () => {
    const valid = JSON.stringify({
      role: 'assistant',
      message: { content: [{ type: 'text', text: 'survivor' }] },
    });
    const objectContent = JSON.stringify({
      role: 'assistant',
      message: { content: { unexpected: 'shape' } },
    });
    const content = [valid, objectContent].join('\n');

    expect(() => extractLastMessageFromJsonl(content, 'assistant', false)).not.toThrow();
    expect(extractLastMessageFromJsonl(content, 'assistant', false)).toBe('survivor');
  });
});

import { afterEach, beforeEach, describe, expect, it } from 'bun:test';
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import {
  addOpenCodePluginReference,
  deregisterOpenCodePluginFromConfig,
  getOpenCodeConfigPath,
  removeOpenCodePluginReference,
  registerOpenCodePluginInConfig,
} from '../../src/services/integrations/OpenCodeInstaller.js';

describe('OpenCode installer config registration', () => {
  let tempDir: string;
  let previousConfigDir: string | undefined;

  beforeEach(() => {
    tempDir = join(tmpdir(), `opencode-installer-test-${Date.now()}-${Math.random().toString(36).slice(2)}`);
    mkdirSync(tempDir, { recursive: true });
    previousConfigDir = process.env.OPENCODE_CONFIG_DIR;
    process.env.OPENCODE_CONFIG_DIR = tempDir;
  });

  afterEach(() => {
    if (previousConfigDir === undefined) {
      delete process.env.OPENCODE_CONFIG_DIR;
    } else {
      process.env.OPENCODE_CONFIG_DIR = previousConfigDir;
    }
    rmSync(tempDir, { recursive: true, force: true });
  });

  it('adds claude-mem to an existing plugin array', () => {
    const config = addOpenCodePluginReference({
      plugin: ['context-mode'],
      mcp: { context7: { enabled: true } },
    });

    expect(config.plugin).toEqual(['context-mode', './plugins/claude-mem.js']);
    expect(config.mcp).toEqual({ context7: { enabled: true } });
  });

  it('does not duplicate an existing claude-mem plugin reference', () => {
    const config = addOpenCodePluginReference({
      plugin: ['context-mode', './plugins/claude-mem.js'],
    });

    expect(config.plugin).toEqual(['context-mode', './plugins/claude-mem.js']);
  });

  it('preserves an existing single-string plugin entry', () => {
    const config = addOpenCodePluginReference({
      plugin: 'context-mode',
    });

    expect(config.plugin).toEqual(['context-mode', './plugins/claude-mem.js']);
  });

  it('removes only claude-mem from plugin entries', () => {
    const config = removeOpenCodePluginReference({
      plugin: ['context-mode', './plugins/claude-mem.js'],
      provider: { openai: { models: {} } },
    });

    expect(config.plugin).toEqual(['context-mode']);
    expect(config.provider).toEqual({ openai: { models: {} } });
  });

  it('creates opencode.json when missing', () => {
    const result = registerOpenCodePluginInConfig();

    expect(result).toBe(0);
    expect(existsSync(getOpenCodeConfigPath())).toBe(true);

    const config = JSON.parse(readFileSync(getOpenCodeConfigPath(), 'utf-8'));
    expect(config.$schema).toBe('https://opencode.ai/config.json');
    expect(config.plugin).toEqual(['./plugins/claude-mem.js']);
  });

  it('preserves existing config fields when registering the plugin', () => {
    writeFileSync(getOpenCodeConfigPath(), JSON.stringify({
      $schema: 'https://opencode.ai/config.json',
      plugin: ['context-mode'],
      provider: { openai: { models: {} } },
    }), 'utf-8');

    const result = registerOpenCodePluginInConfig();

    expect(result).toBe(0);
    const config = JSON.parse(readFileSync(getOpenCodeConfigPath(), 'utf-8'));
    expect(config.plugin).toEqual(['context-mode', './plugins/claude-mem.js']);
    expect(config.provider).toEqual({ openai: { models: {} } });
  });

  it('removes the plugin reference from opencode.json during deregistration', () => {
    writeFileSync(getOpenCodeConfigPath(), JSON.stringify({
      $schema: 'https://opencode.ai/config.json',
      plugin: ['context-mode', './plugins/claude-mem.js'],
    }), 'utf-8');

    const result = deregisterOpenCodePluginFromConfig();

    expect(result).toBe(0);
    const config = JSON.parse(readFileSync(getOpenCodeConfigPath(), 'utf-8'));
    expect(config.plugin).toEqual(['context-mode']);
  });
});

import { describe, it, expect, beforeEach, afterEach, afterAll, mock } from 'bun:test';
import { ClassifiedProviderError } from '../../src/services/worker/provider-errors.js';
import {
  CLAUDE_CLI_SETUP_RECHECK_COOLDOWN_MS,
  getDependencyStatus,
  resetDependencyStatusesForTesting,
} from '../../src/shared/dependency-health.js';
import type { ActiveSession } from '../../src/services/worker-types.js';
// Capture real exports before mock.module mutates the live namespace, then
// re-register the snapshot in afterAll so this mock does not leak into later
// test files (bun's mock.module is process-global; mock.restore() does NOT
// undo it). Without the restore, whichever file runs after this one sees the
// stub — tests/shared/find-claude-executable.test.ts exercises the real
// implementation and fails when the readdir-dependent file order puts it
// after this file (the CI-only findClaudeExecutable failures).
import * as realFindClaudeExecutableModule from '../../src/shared/find-claude-executable.js';

const realFindClaudeExecutableSnapshot = { ...realFindClaudeExecutableModule };

// bun's mock.module is process-global and sticky — it is never auto-unregistered
// and leaks into every test file that runs afterwards in the same process. So
// this mock must be leak-proof in two ways:
//   1. Spread the REAL module through the factory, overriding only
//      findClaudeExecutable. Otherwise the module's other exports (_internals,
//      resetClaudeExecutableCache, CAPABILITY_PROBE_ARGS) vanish for later files
//      like find-claude-executable.test.ts, which drives all of them.
//   2. Default the override to the real implementation and restore it in
//      afterAll, so the per-test stubs below (one of which throws) don't leak
//      out and break unrelated suites (recall-mcp-server, server-boot) that
//      transitively resolve the CLI.
// The real module is snapshotted into a plain object before mocking so the
// captured references can't be live-swapped by the mock registration.
const actualFindClaude = { ...(await import('../../src/shared/find-claude-executable.js')) };
const realFindClaudeExecutable = actualFindClaude.findClaudeExecutable;

type FindClaudeExecutable = typeof realFindClaudeExecutable;
let findClaudeExecutableImpl: (...args: Parameters<FindClaudeExecutable>) => string = realFindClaudeExecutable;

mock.module('../../src/shared/find-claude-executable.js', () => ({
  ...actualFindClaude,
  findClaudeExecutable: (...args: Parameters<FindClaudeExecutable>) => findClaudeExecutableImpl(...args),
}));

afterAll(() => {
  // Point the leaked mock back at the real implementation for subsequent files,
  // then re-register the untouched module snapshot.
  findClaudeExecutableImpl = realFindClaudeExecutable;
  mock.module('../../src/shared/find-claude-executable.js', () => realFindClaudeExecutableSnapshot);
});

const { SessionRoutes } = await import('../../src/services/worker/http/routes/SessionRoutes.js');
const { ClaudeProvider } = await import('../../src/services/worker/ClaudeProvider.js');

function makeSession(): ActiveSession {
  return {
    sessionDbId: 42,
    contentSessionId: 'content-42',
    memorySessionId: null,
    project: 'project',
    platformSource: 'claude',
    userPrompt: 'prompt',
    abortController: new AbortController(),
    generatorPromise: null,
    lastPromptNumber: 1,
    startTime: Date.now(),
    cumulativeInputTokens: 0,
    cumulativeOutputTokens: 0,
    earliestPendingTimestamp: null,
    claimedMessageIds: [],
    conversationHistory: [],
    currentProvider: null,
    consecutiveRestarts: 0,
    consecutiveInvalidOutputs: 0,
    lastGeneratorActivity: Date.now(),
  };
}

describe('Claude setup-required generator gate', () => {
  const realDateNow = Date.now;

  beforeEach(() => {
    resetDependencyStatusesForTesting();
    findClaudeExecutableImpl = () => '/mock/claude';
    Date.now = realDateNow;
  });

  afterEach(() => {
    Date.now = realDateNow;
  });

  it('skips immediate repeat starts, then rechecks and clears status after cooldown repair', async () => {
    const session = makeSession();
    let activeSession: ActiveSession | undefined = session;
    let starts = 0;
    let findAttempts = 0;
    let finalizerCalls = 0;
    let removeSessionImmediateCalls = 0;
    let repairedRunResolve: (() => void) | null = null;

    const sessionManager = {
      getSession: () => activeSession,
      getMessageBuffer: () => ({
        getPendingCount: () => 1,
        peekTypes: () => [],
      }),
      removeSessionImmediate: () => {
        removeSessionImmediateCalls += 1;
        activeSession = undefined;
      },
    };

    const claudeProvider = {
      startSession: async () => {
        starts += 1;
        if (starts === 1) {
          throw new ClassifiedProviderError('Claude executable not found', {
            kind: 'setup_required',
            cause: new Error('Claude executable not found'),
          });
        }
        await new Promise<void>(resolve => {
          repairedRunResolve = resolve;
        });
      },
    };

    const routes = new SessionRoutes(
      sessionManager as any,
      {} as any,
      claudeProvider as any,
      { startSession: async () => {} } as any,
      { startSession: async () => {} } as any,
      {} as any,
      {} as any,
      {
        finalizeSession: async () => {
          finalizerCalls += 1;
        },
      } as any,
    );

    await routes.ensureGeneratorRunning(session.sessionDbId, 'observation');
    await session.generatorPromise;

    expect(starts).toBe(1);
    expect(getDependencyStatus('claude_cli')).toMatchObject({
      kind: 'setup_required',
      remediation: expect.stringContaining('Claude Code CLI'),
    });
    expect(activeSession).toBe(session);
    expect(session.generatorPromise).toBeNull();
    expect(finalizerCalls).toBe(0);
    expect(removeSessionImmediateCalls).toBe(0);

    await routes.ensureGeneratorRunning(session.sessionDbId, 'observation');

    expect(starts).toBe(1);
    expect(findAttempts).toBe(0);
    expect(finalizerCalls).toBe(0);
    expect(removeSessionImmediateCalls).toBe(0);

    findClaudeExecutableImpl = () => {
      findAttempts += 1;
      return '/repaired/claude';
    };
    Date.now = () => realDateNow() + CLAUDE_CLI_SETUP_RECHECK_COOLDOWN_MS + 1;

    await routes.ensureGeneratorRunning(session.sessionDbId, 'observation');

    expect(findAttempts).toBe(1);
    expect(starts).toBe(2);
    expect(getDependencyStatus('claude_cli')).toBeNull();
    expect(session.generatorPromise).not.toBeNull();

    repairedRunResolve?.();
    await session.generatorPromise;

    expect(finalizerCalls).toBe(1);
    expect(removeSessionImmediateCalls).toBe(1);
  });

  it('records Claude CLI remediation when provider startup cannot find the executable', async () => {
    findClaudeExecutableImpl = () => {
      throw new Error('Claude executable not found');
    };

    const provider = new ClaudeProvider({} as any, {} as any);

    await expect(provider.startSession(makeSession())).rejects.toThrow('Claude executable not found');
    expect(getDependencyStatus('claude_cli')).toMatchObject({
      kind: 'setup_required',
      remediation: expect.stringContaining('Claude Code CLI'),
    });
  });
});

// SPDX-License-Identifier: Apache-2.0
//
// #2572 — the server runtime must emit hardening response headers. The worker
// (loopback-only) leaves them off. We assert the opt-in `securityHeaders`
// option installs the headers on every response and is absent by default.

import { afterEach, describe, expect, it, spyOn } from 'bun:test';
import { logger } from '../../src/utils/logger.js';
import { Server, type ServerOptions } from '../../src/services/server/Server.js';

function baseOptions(overrides: Partial<ServerOptions> = {}): ServerOptions {
  return {
    getInitializationComplete: () => true,
    getMcpReady: () => true,
    onShutdown: () => Promise.resolve(),
    onRestart: () => Promise.resolve(),
    workerPath: '/test/worker-service.cjs',
    getAiStatus: () => ({ provider: 'disabled', authMethod: 'api-key', lastInteraction: null }),
    ...overrides,
  };
}

describe('Server security headers (#2572)', () => {
  let server: Server | null = null;
  let spies: ReturnType<typeof spyOn>[] = [];

  afterEach(async () => {
    spies.forEach(s => s.mockRestore());
    spies = [];
    if (server?.getHttpServer()) {
      try { await server.close(); } catch { /* ignore */ }
    }
    server = null;
  });

  it('emits hardening headers on a server response when securityHeaders=true', async () => {
    spies = [spyOn(logger, 'info').mockImplementation(() => {})];
    server = new Server(baseOptions({ securityHeaders: true }));
    const port = 41000 + Math.floor(Math.random() * 9000);
    await server.listen(port, '127.0.0.1');

    const res = await fetch(`http://127.0.0.1:${port}/api/health`);
    expect(res.status).toBe(200);
    expect(res.headers.get('x-content-type-options')).toBe('nosniff');
    expect(res.headers.get('x-frame-options')).toBe('DENY');
    expect(res.headers.get('referrer-policy')).toBe('no-referrer');
    expect(res.headers.get('cross-origin-opener-policy')).toBe('same-origin');
    expect(res.headers.get('x-powered-by')).toBeNull();
  });

  it('does NOT emit the hardening headers by default (worker runtime)', async () => {
    spies = [spyOn(logger, 'info').mockImplementation(() => {})];
    server = new Server(baseOptions());
    const port = 41000 + Math.floor(Math.random() * 9000);
    await server.listen(port, '127.0.0.1');

    const res = await fetch(`http://127.0.0.1:${port}/api/health`);
    expect(res.status).toBe(200);
    expect(res.headers.get('x-content-type-options')).toBeNull();
    expect(res.headers.get('x-frame-options')).toBeNull();
  });
});

import { describe, it, expect, beforeEach, afterEach } from 'bun:test';
import { readFileSync, existsSync, rmSync } from 'fs';
import {
  buildHardenedSdkOptions,
  OBSERVER_DISALLOWED_TOOLS,
} from '../../src/sdk/hardened-options.js';
import {
  recordObserverToolAttempt,
  getObserverAuditLogPath,
} from '../../src/utils/observer-audit.js';
import { OBSERVER_SESSIONS_DIR } from '../../src/shared/paths.js';

const BASE_INPUT = {
  source: 'Observer' as const,
  model: 'claude-sonnet-4-6',
  env: {} as NodeJS.ProcessEnv,
  pathToClaudeCodeExecutable: '/usr/bin/claude',
};

const AUDIT_PATH = getObserverAuditLogPath();

function readAuditLines(): Array<Record<string, unknown>> {
  if (!existsSync(AUDIT_PATH)) return [];
  return readFileSync(AUDIT_PATH, 'utf8')
    .split('\n')
    .filter((l) => l.trim().length > 0)
    .map((l) => JSON.parse(l) as Record<string, unknown>);
}

describe('Observer/KnowledgeAgent SDK tool enforcement (hardened-options)', () => {
  describe('belt + suspenders + braces: option surface', () => {
    it('sets tools to an empty array (disables ALL built-in tools)', () => {
      const opts = buildHardenedSdkOptions({ ...BASE_INPUT });
      expect(Array.isArray(opts.tools)).toBe(true);
      expect(opts.tools).toHaveLength(0);
    });

    it('sets allowedTools to an empty array (nothing auto-approved)', () => {
      const opts = buildHardenedSdkOptions({ ...BASE_INPUT });
      expect(Array.isArray(opts.allowedTools)).toBe(true);
      expect(opts.allowedTools).toHaveLength(0);
    });

    it('keeps the full disallowedTools deny-list (12 tools)', () => {
      const opts = buildHardenedSdkOptions({ ...BASE_INPUT });
      const denied = opts.disallowedTools ?? [];
      for (const tool of OBSERVER_DISALLOWED_TOOLS) {
        expect(denied).toContain(tool);
      }
      expect(denied).toHaveLength(OBSERVER_DISALLOWED_TOOLS.length);
      expect(OBSERVER_DISALLOWED_TOOLS).toHaveLength(12);
    });

    it("uses the most restrictive non-interactive permissionMode ('dontAsk')", () => {
      const opts = buildHardenedSdkOptions({ ...BASE_INPUT });
      expect(opts.permissionMode).toBe('dontAsk');
    });

    it('never uses bypassPermissions', () => {
      const opts = buildHardenedSdkOptions({ ...BASE_INPUT });
      expect(opts.permissionMode).not.toBe('bypassPermissions');
    });

    it('isolates settings, MCP, and extra directories', () => {
      const opts = buildHardenedSdkOptions({ ...BASE_INPUT });
      expect(opts.mcpServers).toEqual({});
      expect(opts.settingSources).toEqual([]);
      expect(opts.strictMcpConfig).toBe(true);
      expect(opts.additionalDirectories).toEqual([]);
    });

    it('jails cwd to OBSERVER_SESSIONS_DIR and never falls back to process.cwd()', () => {
      const opts = buildHardenedSdkOptions({ ...BASE_INPUT });
      expect(opts.cwd).toBe(OBSERVER_SESSIONS_DIR);
      expect(opts.cwd).not.toBe(process.cwd());
    });

    it('exposes a canUseTool callback', () => {
      const opts = buildHardenedSdkOptions({ ...BASE_INPUT });
      expect(typeof opts.canUseTool).toBe('function');
    });
  });

  describe('canUseTool denies every invocation and audit-logs it', () => {
    beforeEach(() => {
      rmSync(AUDIT_PATH, { force: true });
    });
    afterEach(() => {
      rmSync(AUDIT_PATH, { force: true });
    });

    const callCanUseTool = async (
      input: Parameters<typeof buildHardenedSdkOptions>[0],
      toolName: string,
      toolInput: Record<string, unknown>
    ) => {
      const opts = buildHardenedSdkOptions(input);
      const canUseTool = opts.canUseTool;
      if (!canUseTool) throw new Error('canUseTool missing');
      return canUseTool(toolName, toolInput, {
        signal: new AbortController().signal,
        toolUseID: 'test-tool-use-id',
      });
    };

    it('denies Write and records a denied audit entry', async () => {
      const result = await callCanUseTool(
        { ...BASE_INPUT, sessionDbId: 42, contentSessionId: 'cs-1', project: 'demo' },
        'Write',
        { file_path: '/tmp/CLAUDE_MEM_PWNED.txt', content: 'pwned' }
      );
      expect(result.behavior).toBe('deny');

      const lines = readAuditLines();
      expect(lines).toHaveLength(1);
      expect(lines[0].tool_name).toBe('Write');
      expect(lines[0].result).toBe('denied');
      expect(lines[0].source).toBe('Observer');
      expect(lines[0].sessionDbId).toBe(42);
      expect(lines[0].contentSessionId).toBe('cs-1');
      expect(lines[0].project).toBe('demo');
    });

    it('denies Bash, Edit, Read, and Task — all tool names denied', async () => {
      for (const tool of ['Bash', 'Edit', 'Read', 'Task', 'SomeFutureUnknownTool']) {
        const result = await callCanUseTool({ ...BASE_INPUT }, tool, { x: 1 });
        expect(result.behavior).toBe('deny');
        if (result.behavior === 'deny') {
          expect(typeof result.message).toBe('string');
          expect(result.message.length).toBeGreaterThan(0);
        }
      }
      const lines = readAuditLines();
      expect(lines).toHaveLength(5);
      expect(lines.every((l) => l.result === 'denied')).toBe(true);
    });

    it('truncates oversized tool_input in the audit log', async () => {
      const huge = 'A'.repeat(10_000);
      await callCanUseTool({ ...BASE_INPUT }, 'Write', { content: huge });
      const lines = readAuditLines();
      expect(lines).toHaveLength(1);
      const recorded = String(lines[0].tool_input);
      expect(recorded.length).toBeLessThan(huge.length);
      expect(recorded).toContain('[TRUNCATED]');
    });

    it('recordObserverToolAttempt is best-effort and never throws', () => {
      expect(() =>
        recordObserverToolAttempt({
          source: 'KnowledgeAgent',
          tool_name: 'Bash',
          tool_input: { command: 'rm -rf /' },
          result: 'denied',
        })
      ).not.toThrow();
    });
  });

  describe('both call sites are configured identically via the shared helper', () => {
    // Stripping the call-site-specific fields (canUseTool closure identity,
    // resume, source-tagged audit identifiers) must leave IDENTICAL lockdown.
    const lockdownShape = (
      input: Parameters<typeof buildHardenedSdkOptions>[0]
    ) => {
      const o = buildHardenedSdkOptions(input);
      return {
        tools: o.tools,
        allowedTools: o.allowedTools,
        disallowedTools: o.disallowedTools,
        permissionMode: o.permissionMode,
        mcpServers: o.mcpServers,
        settingSources: o.settingSources,
        strictMcpConfig: o.strictMcpConfig,
        additionalDirectories: o.additionalDirectories,
        cwd: o.cwd,
        hasCanUseTool: typeof o.canUseTool === 'function',
      };
    };

    it('Observer and KnowledgeAgent produce the same lockdown shape', () => {
      const observer = lockdownShape({
        source: 'Observer',
        sessionDbId: 1,
        contentSessionId: 'obs',
        project: 'p',
        model: 'm',
        env: {},
        pathToClaudeCodeExecutable: '/c',
        abortController: new AbortController(),
        spawnClaudeCodeProcess: () => ({}) as never,
      });
      const knowledge = lockdownShape({
        source: 'KnowledgeAgent',
        project: 'corpus',
        model: 'm',
        env: {},
        pathToClaudeCodeExecutable: '/c',
        resume: 'session-xyz',
      });
      expect(observer).toEqual(knowledge);
    });
  });
});

import { describe, it, expect, beforeEach, afterEach, spyOn } from 'bun:test';
import * as childProcess from 'child_process';
import * as fs from 'fs';
import { join } from 'path';
import {
  readClaudeOAuthToken,
  decodeJwtExpMs,
  writeStaleMarker,
  clearStaleMarker,
  readStaleMarker,
} from '../../src/shared/oauth-token.js';
import { paths } from '../../src/shared/paths.js';
import { buildIsolatedEnvWithFreshOAuth } from '../../src/shared/EnvManager.js';

/**
 * The implementation uses promisify(execFile), which captures execFile at
 * module-load time. To intercept those calls in tests we replace the export
 * on `child_process` and restore it afterwards. We also redirect DATA_DIR
 * to a per-test temp dir for marker/sidecar tests.
 */

const ORIGINAL_EXEC_FILE = childProcess.execFile;
const ORIGINAL_PLATFORM = process.platform;
const ORIGINAL_ENV_TOKEN = [REDACTED];
const ORIGINAL_DATA_DIR = process.env.CLAUDE_MEM_DATA_DIR;

let dataDirSpy: ReturnType<typeof spyOn> | undefined;
let tempDir: string;

function setPlatform(value: NodeJS.Platform): void {
  Object.defineProperty(process, 'platform', { value, configurable: true });
}

function restorePlatform(): void {
  Object.defineProperty(process, 'platform', { value: ORIGINAL_PLATFORM, configurable: true });
}

/**
 * Patch promisify(execFile) by replacing the underlying execFile with a stub
 * that calls back like the real Node API. Because oauth-token.ts already
 * captured the original at import time, we instead intercept the cached
 * promisified function via the module's internal binding by re-importing.
 *
 * Simpler approach: spy on childProcess.execFile and route calls to a fake
 * callback. Because promisify wraps execFile by reference at import time,
 * we can't intercept post-hoc. Instead we exercise the parsing logic
 * directly via parseKeychainPayload-equivalent paths: we inject results by
 * calling readClaudeOAuthToken() with platform spoofed AND the expected
 * `security`/`secret-tool` binary spy via mocking the `execFile` hostpath.
 *
 * Bun's spyOn lets us replace properties on the `child_process` module
 * object, but the promisified handle inside oauth-token.ts already holds a
 * reference. So we test the parsing layer by exercising decodeJwtExpMs
 * directly and rely on environment-fallback path for the integration shape.
 */

beforeEach(() => {
  // Redirect DATA_DIR to a temp directory for marker file tests.
  tempDir = fs.mkdtempSync(join(fs.realpathSync(require('os').tmpdir()), 'claude-mem-oauth-test-'));
  dataDirSpy = spyOn(paths, 'dataDir').mockImplementation(() => tempDir);
});

afterEach(() => {
  dataDirSpy?.mockRestore();
  restorePlatform();
  if (ORIGINAL_ENV_TOKEN === undefined) {
    delete process.env.CLAUDE_CODE_OAUTH_TOKEN;
  } else {
    process.env.CLAUDE_CODE_OAUTH_TOKEN = [REDACTED];
  }
  if (ORIGINAL_DATA_DIR === undefined) {
    delete process.env.CLAUDE_MEM_DATA_DIR;
  } else {
    process.env.CLAUDE_MEM_DATA_DIR = ORIGINAL_DATA_DIR;
  }
  // Clean up temp dir
  try {
    fs.rmSync(tempDir, { recursive: true, force: true });
  } catch {
    // best effort
  }
});

describe('decodeJwtExpMs', () => {
  it('returns undefined for non-JWT tokens', () => {
    expect(decodeJwtExpMs('[REDACTED]')).toBeUndefined();
    expect(decodeJwtExpMs('not.a.jwt.really')).toBeUndefined();
    expect(decodeJwtExpMs('')).toBeUndefined();
  });

  it('extracts exp claim from a real JWT and converts seconds to ms', () => {
    // header.payload.signature where payload is {"exp": 9999999999}
    const header = Buffer.from(JSON.stringify({ alg: 'none' })).toString('base64url');
    const payload = Buffer.from(JSON.stringify({ exp: 9999999999 })).toString('base64url');
    const signature = 'sig';
    const jwt = `${header}.${payload}.${signature}`;
    expect(decodeJwtExpMs(jwt)).toBe(9999999999 * 1000);
  });

  it('returns undefined when JWT payload has no exp claim', () => {
    const header = Buffer.from(JSON.stringify({ alg: 'none' })).toString('base64url');
    const payload = Buffer.from(JSON.stringify({ sub: 'user' })).toString('base64url');
    const jwt = `${header}.${payload}.sig`;
    expect(decodeJwtExpMs(jwt)).toBeUndefined();
  });

  it('returns undefined for malformed JWT', () => {
    expect(decodeJwtExpMs('not-base64.not-base64.sig')).toBeUndefined();
  });
});

describe('marker file scheme', () => {
  it('writeStaleMarker creates the marker file with the reason', () => {
    writeStaleMarker('token expired at 2026-01-01');
    const markerPath = join(tempDir, 'oauth-stale.marker');
    expect(fs.existsSync(markerPath)).toBe(true);
    expect(fs.readFileSync(markerPath, 'utf-8')).toBe('token expired at 2026-01-01');
  });

  it('readStaleMarker returns undefined when no marker exists', () => {
    expect(readStaleMarker()).toBeUndefined();
  });

  it('readStaleMarker returns the reason after writeStaleMarker', () => {
    writeStaleMarker('refresh me');
    expect(readStaleMarker()).toBe('refresh me');
  });

  it('clearStaleMarker removes an existing marker', () => {
    writeStaleMarker('temporary');
    expect(readStaleMarker()).toBe('temporary');
    clearStaleMarker();
    expect(readStaleMarker()).toBeUndefined();
  });

  it('clearStaleMarker is a no-op when no marker exists', () => {
    expect(() => clearStaleMarker()).not.toThrow();
  });
});

describe('readClaudeOAuthToken — env-fallback branch', () => {
  // These tests exercise the env-fallback path which is reachable on every
  // platform when the keychain returns absent. We force absent by spoofing
  // the platform to an unsupported value.
  beforeEach(() => {
    setPlatform('aix' as NodeJS.Platform); // unsupported -> always absent
  });

  it('returns absent when no env token is set', async () => {
    delete process.env.CLAUDE_CODE_OAUTH_TOKEN;
    const result = await readClaudeOAuthToken();
    expect(result.kind).toBe('absent');
    if (result.kind === 'absent') {
      expect(result.reason).toContain('Unsupported platform');
    }
  });

  it('returns present (env-fallback) when env token is set and not expired', async () => {
    // Non-JWT bare token, no sidecar -> no expiresAt detectable -> not expired.
    process.env.CLAUDE_CODE_OAUTH_TOKEN = '[REDACTED]';
    const result = await readClaudeOAuthToken();
    expect(result.kind).toBe('present');
    if (result.kind === 'present') {
      expect(result.token).toBe('sk-ant-oat01-fallback');
      expect(result.source).toBe('env-fallback');
    }
  });

  it('returns expired when env token JWT exp claim is in the past', async () => {
    // Build a JWT with exp=1 (1970) — definitely expired.
    const header = Buffer.from(JSON.stringify({ alg: 'none' })).toString('base64url');
    const payload = Buffer.from(JSON.stringify({ exp: 1 })).toString('base64url');
    const expiredJwt = `${header}.${payload}.sig`;
    process.env.CLAUDE_CODE_OAUTH_TOKEN = expiredJwt;
    const result = await readClaudeOAuthToken();
    expect(result.kind).toBe('expired');
    if (result.kind === 'expired') {
      expect(result.reason).toContain('expired');
      expect(result.expiresAt).toBe(1000); // 1 sec * 1000
    }
  });

  it('returns expired when sidecar metadata indicates env token is stale', async () => {
    process.env.CLAUDE_CODE_OAUTH_TOKEN = '[REDACTED]';
    // Write a sidecar with expiresAt in the past (well beyond grace window).
    const sidecarPath = join(tempDir, 'oauth-token-meta.json');
    const stalePastMs = Date.now() - 60 * 60 * 1000; // 1 hour ago
    fs.writeFileSync(sidecarPath, JSON.stringify({ expiresAt: stalePastMs }));
    const result = await readClaudeOAuthToken();
    expect(result.kind).toBe('expired');
    if (result.kind === 'expired') {
      expect(result.expiresAt).toBe(stalePastMs);
    }
  });

  it('returns present when sidecar expiresAt is in the future', async () => {
    process.env.CLAUDE_CODE_OAUTH_TOKEN = '[REDACTED]';
    const sidecarPath = join(tempDir, 'oauth-token-meta.json');
    const futureMs = Date.now() + 60 * 60 * 1000; // 1 hour from now
    fs.writeFileSync(sidecarPath, JSON.stringify({ expiresAt: futureMs }));
    const result = await readClaudeOAuthToken();
    expect(result.kind).toBe('present');
    if (result.kind === 'present') {
      expect(result.expiresAt).toBe(futureMs);
      expect(result.source).toBe('env-fallback');
    }
  });
});

describe('readClaudeOAuthToken — macOS keychain branch', () => {
  // We can't easily intercept the cached promisified execFile from inside
  // oauth-token.ts (it captured a reference at module load). Instead we
  // verify the macOS branch dispatches by checking that on darwin without
  // a real keychain entry, the fallback path is reached.
  it('on macOS, falls back to env when keychain access fails or returns nothing', async () => {
    if (process.platform !== 'darwin') {
      // Skip on non-macOS — we only run this test where security CLI exists.
      return;
    }
    // Use an env token; if the real keychain has a fresh entry, we get
    // 'present' with source='keychain'. If no keychain entry, we fall back
    // to env-fallback. Either way, kind='present' with a non-empty token
    // (or 'expired' if the real keychain entry happens to be stale).
    process.env.CLAUDE_CODE_OAUTH_TOKEN = '[REDACTED]';
    setPlatform('darwin');
    const result = await readClaudeOAuthToken();
    // Whatever the keychain says, the result should be a valid kind.
    expect(['present', 'expired', 'absent']).toContain(result.kind);
    if (result.kind === 'present') {
      expect(result.token.length).toBeGreaterThan(0);
      expect(['keychain', 'env-fallback']).toContain(result.source);
    }
  });
});

describe('readClaudeOAuthToken — Linux branch', () => {
  it('on linux without secret-tool, returns absent gracefully', async () => {
    if (process.platform !== 'linux') return; // skip on non-linux
    setPlatform('linux');
    delete process.env.CLAUDE_CODE_OAUTH_TOKEN;
    const result = await readClaudeOAuthToken();
    // If secret-tool is not installed or has no entry, returns absent.
    // If somehow present, we accept that too.
    expect(['present', 'expired', 'absent']).toContain(result.kind);
  });
});

describe('readClaudeOAuthToken — Windows branch', () => {
  it('on win32 without keychain entry, returns absent or env-fallback', async () => {
    if (process.platform !== 'win32') return; // skip on non-windows
    setPlatform('win32');
    delete process.env.CLAUDE_CODE_OAUTH_TOKEN;
    const result = await readClaudeOAuthToken();
    expect(['present', 'expired', 'absent']).toContain(result.kind);
    if (result.kind === 'absent') {
      expect(result.reason).not.toContain('Windows Credential Manager read failed');
      expect(result.reason).toContain('Windows Credential Manager has no entry');
    }
  });
});

// CodeRabbit Minor (PR #2282 follow-up): when the OAuth token is absent, any
// previously-written stale marker is no longer accurate (the token is gone,
// not expired). buildIsolatedEnvWithFreshOAuth must clear it on the absent
// branch the same way it does on present.
describe('buildIsolatedEnvWithFreshOAuth — absent token clears stale marker', () => {
  beforeEach(() => {
    setPlatform('aix' as NodeJS.Platform); // unsupported -> always absent
    delete process.env.CLAUDE_CODE_OAUTH_TOKEN;
  });

  it('clears a pre-existing stale marker when token is absent', async () => {
    // Pre-existing marker from an earlier "expired" pass.
    writeStaleMarker('left over from previous run');
    expect(readStaleMarker()).toBe('left over from previous run');

    // Force the absent path: ANTHROPIC_API_KEY must NOT be set in either the
    // env file or the process env, otherwise the early-return branch fires
    // before we ever reach the OAuth resolution.
    const origAnthropicKey = process.env.ANTHROPIC_API_KEY;
    delete process.env.ANTHROPIC_API_KEY;
    try {
      await buildIsolatedEnvWithFreshOAuth(true);
    } finally {
      if (origAnthropicKey !== undefined) {
        process.env.ANTHROPIC_API_KEY = [REDACTED];
      }
    }

    expect(readStaleMarker()).toBeUndefined();
  });
});

